from shop.pricing import line_total, order_total
from decimal import Decimal, ROUND_HALF_UP
def rh(v): return int(Decimal(v).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
# brute-force cross-check against a naive exact-arithmetic reference
import itertools
for u in range(1, 400):
    for q in list(range(0, 12)) + [50, 123]:
        ref = u*q
        if q >= 10:
            ref = rh(Decimal(u*q) * 9 / 10)
        assert line_total(u, q) == ref, (u, q)
for u in range(1, 300):
    for q in range(1, 13):
        for c in range(0, 50, 7):
            sub = line_total(u, q)
            d = rh(Decimal(sub)*c/100)
            t = rh(Decimal(sub-d)*10/100)
            r = order_total([(u,q)], coupon_pct=c)
            assert r == {"subtotal": sub, "discount": d, "tax": t, "total": sub-d+t}, (u,q,c,r)
